//! Isolated development WASM transport. No production activation. No unsafe blocks.
//! JS may write only the staging allocation, then read copied response/output before release.
use hkia_save_core::{abi,archive::MAX_ARCHIVE,envelope::Version,session::*,writer::{Edit,Field,Scalar,PlanInfo,Proof,MAX_EDITS},Error};
use std::cell::RefCell;
const MAX_FRAME:usize=4096;
const MAX_META:usize=32*1024;
const MAGIC:[u8;4]=*b"HKE1";
struct Bridge{session:Option<ProductSession>,stage:Vec<u8>,reply:Vec<u8>,output:Vec<u8>}
impl Bridge{fn new()->Self{Self{session:None,stage:Vec::new(),reply:Vec::new(),output:Vec::new()}}}
thread_local!{static BRIDGE:RefCell<Bridge>=RefCell::new(Bridge::new());}
// wasm32 addresses are returned as u32. Native tests exercise pure frame functions only.
#[no_mangle] pub extern "C" fn hkia_stage(n:u32)->u32{BRIDGE.with(|c|{let mut b=c.borrow_mut();b.reply=Vec::new();b.output=Vec::new();b.stage=Vec::new();if n==0||n as usize>MAX_ARCHIVE+MAX_FRAME{return 0}b.stage=vec![0;n as usize];b.stage.as_mut_ptr() as usize as u32})}
#[no_mangle] pub extern "C" fn hkia_init()->u32{BRIDGE.with(|c|{let mut b=c.borrow_mut();let v=std::mem::take(&mut b.stage);if b.session.is_some()||v.len()!=16{return 1}match ProductSession::new_private_writer(v.as_slice().try_into().unwrap()){Ok(s)=>{b.session=Some(s);0},Err(_)=>1}})}
#[no_mangle] pub extern "C" fn hkia_invoke(frame_len:u32)->u32{BRIDGE.with(|c|{let mut b=c.borrow_mut();b.reply=Vec::new();b.output=Vec::new();let mut v=std::mem::take(&mut b.stage);let n=frame_len as usize;if n<78||n>MAX_FRAME||n>v.len(){return 1}let input=v.split_off(n);let Some(s)=b.session.as_mut()else{return 1};let result=if v[..4]==abi::MAGIC{abi::dispatch_frame(s,&v,if input.is_empty(){None}else{Some(input)}).map(|r|(r,Vec::new()))}else if v[..4]==MAGIC&&input.is_empty(){dispatch(s,&v)}else{Err(SessionError::Protocol)};match result{Ok((r,o))if r.len()<=MAX_META&&o.len()<=MAX_ARCHIVE=>{b.reply=r;b.output=o;0},_=>1}})}
#[no_mangle] pub extern "C" fn hkia_reply_ptr()->u32{BRIDGE.with(|c|c.borrow().reply.as_ptr() as usize as u32)}
#[no_mangle] pub extern "C" fn hkia_reply_len()->u32{BRIDGE.with(|c|c.borrow().reply.len() as u32)}
#[no_mangle] pub extern "C" fn hkia_output_ptr()->u32{BRIDGE.with(|c|c.borrow().output.as_ptr() as usize as u32)}
#[no_mangle] pub extern "C" fn hkia_output_len()->u32{BRIDGE.with(|c|c.borrow().output.len() as u32)}
#[no_mangle] pub extern "C" fn hkia_release(){BRIDGE.with(|c|{let mut b=c.borrow_mut();b.stage=Vec::new();b.reply=Vec::new();b.output=Vec::new()})}
struct Reader<'a>{b:&'a[u8],p:usize}
impl<'a> Reader<'a>{fn take<const N:usize>(&mut self)->Result<[u8;N],SessionError>{let end=self.p.checked_add(N).ok_or(SessionError::Protocol)?;let a=self.b.get(self.p..end).ok_or(SessionError::Protocol)?.try_into().unwrap();self.p=end;Ok(a)}fn u8(&mut self)->Result<u8,SessionError>{Ok(self.take::<1>()?[0])}fn u16(&mut self)->Result<u16,SessionError>{Ok(u16::from_le_bytes(self.take()?))}fn u32(&mut self)->Result<u32,SessionError>{Ok(u32::from_le_bytes(self.take()?))}fn u64(&mut self)->Result<u64,SessionError>{Ok(u64::from_le_bytes(self.take()?))}fn i32(&mut self)->Result<i32,SessionError>{Ok(i32::from_le_bytes(self.take()?))}fn i64(&mut self)->Result<i64,SessionError>{Ok(i64::from_le_bytes(self.take()?))}}
fn parse(frame:&[u8])->Result<WriterRequest,SessionError>{if frame.len()>MAX_FRAME{return Err(SessionError::Protocol)}let mut r=Reader{b:frame,p:0};if r.take::<4>()?!=MAGIC{return Err(SessionError::Protocol)}let op=r.u8()?;let id=r.u64()?;let runtime=r.take()?;let generation=r.u64()?;let revision=r.u64()?;let present=r.u8()?;let hash=r.take::<32>()?;let source=match present{0 if hash==[0;32]=>None,1=>Some(hash),_=>return Err(SessionError::Protocol)};let command=match op{1=>{let n=r.u16()? as usize;if n==0||n>MAX_EDITS{return Err(SessionError::Protocol)}let mut edits=Vec::with_capacity(n);for _ in 0..n{edits.push(match r.u8()?{1=>Edit::History{item:r.i32()?,old:r.i64()?,next:r.i64()?},2=>Edit::FwishesProgress{achievement:r.u32()?,counter:r.u32()?,old_bits:r.u32()?,next_bits:r.u32()?},_=>return Err(SessionError::Protocol)})}WriterCommand::Plan{edits}},2=>WriterCommand::Preview{plan:r.u64()?},3=>WriterCommand::Apply{plan:r.u64()?},4=>WriterCommand::Verify,5=>WriterCommand::Export,6=>WriterCommand::Backup,7=>WriterCommand::Undo,8=>WriterCommand::Redo,9=>WriterCommand::Reset,_=>return Err(SessionError::Protocol)};if r.p!=frame.len(){return Err(SessionError::Protocol)}Ok(WriterRequest{id,expected:Stamp{runtime,generation,revision,source},command})}
fn u32le(v:&mut Vec<u8>,x:u32){v.extend(x.to_le_bytes())}fn stamp(v:&mut Vec<u8>,s:Stamp){v.extend(s.runtime);v.extend(s.generation.to_le_bytes());v.extend(s.revision.to_le_bytes());v.push(u8::from(s.source.is_some()));v.extend(s.source.unwrap_or([0;32]));}
fn scalar(v:&mut Vec<u8>,s:Scalar){match s{Scalar::Ticks(x)=>{v.push(1);v.extend(x.to_le_bytes())},Scalar::F32Bits(x)=>{v.push(2);u32le(v,x)}}}
fn plan(v:&mut Vec<u8>,p:&PlanInfo){v.extend(p.id.to_le_bytes());v.push(match p.version{Version::V300=>1,Version::V301=>2});v.extend(p.base);v.extend(p.schema);v.extend((p.fields.len()as u16).to_le_bytes());for d in &p.fields{match d.field{Field::History(i)=>{v.push(1);v.extend(i.to_le_bytes())},Field::Achievement(i,g)|Field::Counter(i,g)=>{v.push(if matches!(d.field,Field::Achievement(..)){2}else{3});u32le(v,i);for n in g{u32le(v,n)}}}u32le(v,d.span.start as u32);u32le(v,d.span.end as u32);scalar(v,d.old);scalar(v,d.next);v.extend(d.old_sha)}}
fn proof(v:&mut Vec<u8>,p:&Proof){v.extend(p.digest);for n in [p.bytes,p.fields,p.reused_blocks,p.reencoded_blocks,p.non_target_frames]{u32le(v,n)}}
fn error(e:SessionError)->(u8,u8){match e{SessionError::Foreign=>(1,0),SessionError::Replay=>(2,0),SessionError::Stale=>(3,0),SessionError::NoOpen=>(4,0),SessionError::NoDomain=>(5,0),SessionError::Range=>(6,0),SessionError::Unsupported=>(7,0),SessionError::Overflow=>(8,0),SessionError::Protocol=>(9,0),SessionError::Input(e)=>(10,match e{Error::Budget=>1,Error::Truncated=>2,Error::InvalidDistance=>3,Error::LengthMismatch=>4,Error::Overflow=>5,Error::InvalidToken=>6,Error::Schema=>7,Error::Version=>8,Error::Marker=>9,Error::Duplicate=>10,Error::Trailing=>11})}}
fn dispatch(s:&mut ProductSession,frame:&[u8])->Result<(Vec<u8>,Vec<u8>),SessionError>{let r=s.dispatch_writer(parse(frame)?);let mut v=MAGIC.to_vec();v.extend(r.id.to_le_bytes());stamp(&mut v,r.stamp);match r.result{Err(e)=>{let(a,b)=error(e);v.extend([0,a,b]);if r.output.is_some(){return Err(SessionError::Protocol)}},Ok(p)=>{v.push(1);match p{WriterPayload::Plan(p)=>{v.push(1);plan(&mut v,&p)},WriterPayload::Preview{plan:p,proof:q}=>{v.push(2);plan(&mut v,&p);proof(&mut v,&q)},WriterPayload::Applied(p)=>{v.push(3);proof(&mut v,&p)},WriterPayload::Verified(p)=>{v.push(4);proof(&mut v,&p)},WriterPayload::Exported{digest,bytes}=>{v.push(5);v.extend(digest);u32le(&mut v,bytes)},WriterPayload::Backup{digest,bytes}=>{v.push(6);v.extend(digest);u32le(&mut v,bytes)},WriterPayload::Restored{digest,edited}=>{v.push(7);v.extend(digest);v.push(u8::from(edited))}}}}Ok((v,r.output.unwrap_or_default()))}
#[cfg(test)] mod tests{use super::*;fn frame(op:u8,id:u64,s:Stamp)->Vec<u8>{let mut v=MAGIC.to_vec();v.push(op);v.extend(id.to_le_bytes());stamp(&mut v,s);v}#[test]fn malformed_and_shared_replay(){let mut s=ProductSession::new_private_writer([1;16]).unwrap();let st=s.stamp();let mut f=frame(1,1,st);f.extend([0,0]);assert!(dispatch(&mut s,&f).is_err());let f=frame(5,1,st);let (r,o)=dispatch(&mut s,&f).unwrap();assert_eq!(&r[77..],[0,4,0]);assert!(o.is_empty());let (r,_)=dispatch(&mut s,&f).unwrap();assert_eq!(&r[77..],[0,2,0]);}#[test]fn plan_parse_exact(){let s=ProductSession::new_private_writer([1;16]).unwrap();let mut f=frame(1,1,s.stamp());f.extend(1u16.to_le_bytes());f.push(1);f.extend((-5i32).to_le_bytes());f.extend(i64::MIN.to_le_bytes());f.extend(i64::MAX.to_le_bytes());let r=parse(&f).unwrap();assert!(matches!(r.command,WriterCommand::Plan{edits}if edits==vec![Edit::History{item:-5,old:i64::MIN,next:i64::MAX}]));f.push(0);assert!(parse(&f).is_err());}}
#[cfg(test)]mod execution_tests{use super::*;const A:&[u8]=include_bytes!("../../tests/fixtures/writer-3.0.0-good.zip");const B:&[u8]=include_bytes!("../../tests/fixtures/writer-3.0.1-good.zip");fn frame(m:[u8;4],op:u8,id:u64,s:Stamp)->Vec<u8>{let mut b=m.to_vec();b.push(op);b.extend(id.to_le_bytes());stamp(&mut b,s);b}fn call(s:&mut ProductSession,op:u8,id:u64,extra:&[u8])->(Vec<u8>,Vec<u8>){let mut f=frame(MAGIC,op,id,s.stamp());f.extend(extra);dispatch(s,&f).unwrap()}#[test]fn writer_frames_both_versions(){for raw in [A,B]{let mut s=ProductSession::new_private_writer([9;16]).unwrap();let mut f=frame(abi::MAGIC,1,1,s.stamp());f.push(1);assert_eq!(abi::dispatch_frame(&mut s,&f,Some(raw.to_vec())).unwrap()[77],1);let mut edit=1u16.to_le_bytes().to_vec();edit.push(1);edit.extend(2i32.to_le_bytes());edit.extend(638000000000000001i64.to_le_bytes());edit.extend(638000000010000001i64.to_le_bytes());let (p,o)=call(&mut s,1,2,&edit);assert_eq!(&p[77..79],&[1,1]);assert!(o.is_empty());assert_eq!(s.stamp().revision,0);let (p,o)=call(&mut s,2,3,&2u64.to_le_bytes());assert_eq!(&p[77..79],&[1,2]);assert!(o.is_empty());let (p,_)=call(&mut s,3,4,&2u64.to_le_bytes());assert_eq!(&p[77..79],&[1,3]);assert_eq!(s.stamp().revision,1);let(p,o)=call(&mut s,5,5,&[]);assert_eq!(&p[77..],[0,7,0]);assert!(o.is_empty());let(p,_)=call(&mut s,4,6,&[]);assert_eq!(&p[77..79],&[1,4]);let(p,o)=call(&mut s,5,7,&[]);assert_eq!(&p[77..79],&[1,5]);assert_ne!(o,raw);let(p,b)=call(&mut s,6,8,&[]);assert_eq!(&p[77..79],&[1,6]);assert_eq!(b,raw);}}
#[test]fn frame_bounds_and_cross_protocol_replay(){let mut s=ProductSession::new_private_writer([8;16]).unwrap();let f=frame(abi::MAGIC,3,1,s.stamp());assert_eq!(&abi::dispatch_frame(&mut s,&f,None).unwrap()[77..],[0,4,0]);let f=frame(MAGIC,6,1,s.stamp());assert_eq!(&dispatch(&mut s,&f).unwrap().0[77..],[0,2,0]);let mut f=frame(MAGIC,1,2,s.stamp());f.extend(129u16.to_le_bytes());assert!(parse(&f).is_err());let f=vec![0;MAX_FRAME+1];assert!(parse(&f).is_err());}}
